if(typeof islamQuestions!=='undefined'){for(let i=islamQuestions.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[islamQuestions[i],islamQuestions[j]]=[islamQuestions[j],islamQuestions[i]];}if(localStorage.getItem('strictModeEnabled')==='true'){setTimeout(()=>{const hp=document.getElementById('help-panel-box');if(hp)hp.style.display='none';},50);}window.shareMySuccess=function(score){const textToShare=`🎯 حققت نسبة ${score}% في محاكي الرخصة المهنية الصارم (تخصص الدراسات الإسلامية) جرب اختبار تخصصك الآن وتحدى نفسك لضمان رخصتك: https://asiltrain76.github.io/train/index.html`;navigator.clipboard.writeText(textToShare).then(()=>{alert("📋 تم نسخ نص الإنجاز الفخم! شاركه الآن مع زملائك المعلمين لدعوتهم للتحدي.");}).catch(err=>{console.error('خطأ في النسخ: ',err);});};setInterval(()=>{const resCont=document.getElementById('result-container');const scoreElem=document.getElementById('final-score');if(resCont&&!resCont.classList.contains('hidden')&&scoreElem&&!document.getElementById('share-btn-wrapper')){const textMatch=scoreElem.innerText.match(/([\d.]+)%/);if(textMatch&&textMatch){const pct=parseFloat(textMatch);if(pct>=70){const div=document.createElement('div');div.id='share-btn-wrapper';div.style="margin-top: 15px; padding: 12px; background: rgba(56, 161, 105, 0.1); border-radius: 8px; border: 1px dashed var(--success); text-align: right;";div.innerHTML=`<p style="color: var(--success); font-weight: bold; margin-bottom: 8px;">🎉 كفو يا أستاذ! لقد تجاوزت نسبة الاجتياز وعادلت الفخامة بمعدل ${pct}%!</p><button onclick="shareMySuccess(${pct})" style="background-color: var(--success); color: white; border: none; padding: 10px 15px; font-weight: bold; border-radius: 5px; cursor: pointer; width: 100%;">📢 شارك إنجازك في تويتر وتليجرام وافخر بنفسك</button>`;scoreElem.appendChild(div);}}}},500);}
